Given two integers m and n representing the dimensions of a matrix mat[][] of size m × n, the matrix is initially filled with numbers from 1 to m × n in row-major order.You are also given a 2D array queries[][] of size q × 3. Each query is of the form [t, x, y], where:If t = 1, swap the x-th and y-th rows of the matrix.If t = 2, swap the x-th and y-th columns of the matrix.If t = 3, print the element at position (x, y).Process all the queries in order and output the result for each query of type 3.Examples: Input: m = 3, n = 3query[][] = [[1, 0, 1],                     [3, 0, 0],                     [3, 1, 0],                     [2, 0, 1],                     [3, 0, 0],                     [3, 1, 0]]      Output: [4 , 1,  5,  2]Explanation: Initially the matrix is:mat[][] = [[1, 2, 3],                   [4, 5, 6],                  [7, 8, 9]]First Operation [1, 0, 1]: We need to swap row 0 and row 1.After this operation, matrix becomes:mat[][] =[[4, 5, 6],                  [1, 2, 3],                  [7, 8, 9]]For the next two operation, we are required to print the elements at given cells.Fourth Operation [2, 0, 1]: We need to swap column 0 and column 1.After this operation matrix becomes:mat[][] =[[5, 4, 6],                  [2, 1, 3],                  [8, 7, 9]]For the next two operation, we are required to print the elements at given cells.Try It YourselfTable of Content[Naive Approach] - O(q × n) Time and O(m × n) Space[Expected Approach] - Using Auxiliary Arrays - O(q) Time and O(m + n) Space[Naive Approach] - O(q × n) Time and O(m × n) SpaceThe idea is to create a matrix mat[][] of order m*n, initially filled with integers from 1 to m × n sequentially in a row-major order. For the queries of type 1 and 2, i.e. swap, traverse required row or column and swap the each of its elements. And for the query of type 3, i.e. print, we simply print the element at specified index.
            C++

    #include <iostream>
#include<vector>
using namespace std;

// function to swap rows of the matrix.
void swapRows(vector<vector<int>> &mat, int r1, int r2) {
    for (int i = 0; i < mat[0].size(); i++) {
        swap(mat[r1][i], mat[r2][i]);
    }
}

// function to swap columns of the matrix.
void swapCols(vector<vector<int>> &mat, int c1, int c2) {
    for (int i = 0; i < mat.size(); i++) {
        swap(mat[i][c1], mat[i][c2]);
    }
}

void solveQueries(int m, int n, vector<vector<int>> &query) {

    // create a matrix or order m*n, filled with
    // values from 1 to m*n.
    vector<vector<int>> mat(m, vector<int>(n));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            mat[i][j] = (i * n) + j + 1;
        }
    }

    for (int i = 0; i < query.size(); i++) {

        // type 1 queries
        if (query[i][0] == 1) {
            swapRows(mat, query[i][1], query[i][2]);
        }

        // type 2 queries
        else if (query[i][0] == 2) {
            swapCols(mat, query[i][1], query[i][2]);
        }

        // type 3 queries
        else {
            cout << mat[query[i][1]][query[i][2]] << " ";
        }
    }
}

int main() {
    int m = 3, n = 3;
    vector<vector<int>> query = {{1, 0, 1},
                                 {3, 0, 0},
                                 {3, 1, 0},
                                 {2, 0, 1},
                                 {3, 0, 0},
                                 {3, 1, 0}};
    solveQueries(m, n, query);
    return 0;
}


